        STOP_FOR_TOOL,
      ],
      [{type: 'text', text: '18C in Berlin'}, STOP_DONE],
    ];
    const provider: AIProvider = {
      async *sendMessage(params: SendMessageParams): AsyncGenerator<MessageChunk> {
        seenMessages.push(params.messages);
        for (const chunk of rounds[seenMessages.length - 1] ?? []) yield chunk;
      },
      async generateStructured<T>(): Promise<T> {
        return {} as T;
      },
    };
    const registry = new ToolRegistry();
    const receivedLocations: unknown[] = [];
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async input => {
        receivedLocations.push(input.location);
        return `Sunny in ${String(input.location)}`;
      }
    );

    const orchestrator = createChatOrchestrator(provider, promptBuilder, registry);
    const reply = await orchestrator.processMessage(createSession('weather in Berlin?'));
    const secondRoundSerialized = JSON.stringify(seenMessages[1]);

    expect({
      reply,
      receivedLocations,
      secondRoundMentionsToolRejection: secondRoundSerialized.includes('Invalid input for tool "get_weather"'),
      secondRoundNamesMissingField: secondRoundSerialized.includes('location'),
    }).toEqual({
      reply: '18C in Berlin',
      receivedLocations: ['Berlin'],
      secondRoundMentionsToolRejection: true,
      secondRoundNamesMissingField: true,
    });
  });
});

